import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 업로드 양식(첫 줄 머리글) 열 순서. 입력 문서에 양식 정의가 없어 정한 값이다.
const HEADERS = ['자산코드', '자산번호', '자산명', '자산유형', '자산분류', '위치', '취득일', '취득원가', '상각여부', '상각방법', '내용연수', '상각시작일'];
// 가정: 등록 시 사용 여부 초기값
const INITIAL_USE_STATUS = '사용';

interface ErrorRow {
  row: number;
  reason: string;
}

function isValidDate(text: string): boolean {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
  if (!m) {
    return false;
  }
  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);
  if (month < 1 || month > 12 || day < 1) {
    return false;
  }
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day <= days[month - 1];
}

function parseBool(text: string): boolean | null {
  const v = text.toLowerCase();
  if (['y', '예', 'true', '1'].includes(v)) {
    return true;
  }
  if (['n', '아니오', 'false', '0'].includes(v)) {
    return false;
  }
  return null;
}

@Controller('api/v1')
export class FnSfr02504Controller {
  @Post('/fixed-assets/upload')
  @HttpCode(200)
  async uploadFixedAssets(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const data = checks.inputOf(req.body);
    const file = data['file'];
    if (typeof file !== 'string' || file.trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '자산정보 엑셀 파일을 입력하세요.');
    }
    const lines = file.split(/\r?\n/);
    const delimiter = lines[0].includes('\t') ? '\t' : ',';
    const header = lines[0].split(delimiter).map((h) => h.trim());
    if (header.length !== HEADERS.length || HEADERS.some((h, i) => h !== header[i])) {
      throw new ApiError(422, 'EXCEL_TEMPLATE_MISMATCH', '엑셀 양식이 일치하지 않습니다. 업로드 양식을 확인하세요.');
    }
    return transaction(async (db) => {
      const errorRows: ErrorRow[] = [];
      const seen = new Set<string>();
      let successCount = 0;
      for (let i = 1; i < lines.length; i++) {
        if (lines[i].trim() === '') {
          continue;
        }
        const rowNo = i + 1;
        const c = lines[i].split(delimiter).map((v) => v.trim());
        const [assetCode, assetNo, assetName, assetType, assetCategory, location, acqDate, acqCost, depText, method, lifeText, startDate] = c;
        const reasons: string[] = [];
        if (!assetCode) reasons.push('자산코드 필수');
        if (!assetNo) reasons.push('자산번호 필수');
        if (!assetName) reasons.push('자산명 필수');
        if (!acqDate) {
          reasons.push('취득일 필수');
        } else if (!isValidDate(acqDate)) {
          reasons.push('취득일 형식 오류(YYYY-MM-DD)');
        }
        if (!acqCost) {
          reasons.push('취득원가 필수');
        } else if (!/^\d+(\.\d{1,2})?$/.test(acqCost)) {
          reasons.push('취득원가는 0 이상의 숫자여야 함');
        }
        const dep = parseBool(depText || '');
        if (dep === null) {
          reasons.push('상각여부 필수(Y/N)');
        }
        if (lifeText && !/^[1-9]\d*$/.test(lifeText)) {
          reasons.push('내용연수는 1 이상의 정수여야 함');
        }
        if (startDate && !isValidDate(startDate)) {
          reasons.push('상각시작일 형식 오류(YYYY-MM-DD)');
        }
        if (dep === true) {
          if (!method) reasons.push('상각방법 필수');
          if (!lifeText) reasons.push('내용연수 필수');
          if (!startDate) reasons.push('상각시작일 필수');
        }
        if (startDate && acqDate && isValidDate(startDate) && isValidDate(acqDate) && startDate < acqDate) {
          reasons.push('상각시작일은 취득일 이후여야 함');
        }
        if (reasons.length === 0) {
          const key = assetCode + '\u0000' + assetNo;
          const found = await db.query(
            'SELECT fixed_asset_id FROM fixed_asset WHERE asset_code = :assetCode AND asset_no = :assetNo',
            { assetCode, assetNo },
          );
          if (seen.has(key) || found.length > 0) {
            reasons.push('자산번호 중복');
          }
          seen.add(key);
        }
        if (reasons.length > 0) {
          errorRows.push({ row: rowNo, reason: reasons.join(', ') });
          continue;
        }
        await db.execute(
          'INSERT INTO fixed_asset (asset_code, asset_no, asset_name, asset_type, asset_category, location, acquisition_date, acquisition_cost, is_depreciable, depreciation_method, useful_life_years, depreciation_start_date, use_status, created_at, updated_at) ' +
            'VALUES (:assetCode, :assetNo, :assetName, :assetType, :assetCategory, :location, CAST(:acqDate AS date), CAST(:acqCost AS numeric), CAST(:dep AS boolean), :method, CAST(:life AS integer), CAST(:startDate AS date), :useStatus, now(), now())',
          {
            assetCode,
            assetNo,
            assetName,
            assetType: assetType || null,
            assetCategory: assetCategory || null,
            location: location || null,
            acqDate,
            acqCost,
            dep: dep ? 'true' : 'false',
            method: method || null,
            life: lifeText || null,
            startDate: startDate || null,
            useStatus: INITIAL_USE_STATUS,
          },
        );
        successCount += 1;
      }
      return { successCount, errorRows };
    });
  }
}

