import { useState } from 'react';
import { call, Band, DataTable, Drawer, Form, Field, TextInput, Tiles, ErrorText } from '../kit';
import type { PageProps, Row } from '../kit';

interface UploadResult {
  successCount: number;
  errorRows: Row[];
}

export default function FnSfr02504Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [file, setFile] = useState('');
  const [result, setResult] = useState<UploadResult | undefined>(undefined);

  const submit = async () => {
    if (file.trim() === '') {
      throw new Error('자산정보 엑셀 파일 내용을 입력하세요.');
    }
    const res = await call<UploadResult>('POST', '/fixed-assets/upload', role, { file });
    setResult(res);
    setOpen(false);
    setFile('');
    notify('자산정보를 업로드했습니다.');
  };

  const errorRows = result ? result.errorRows : [];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>업로드 결과</h2>
        <Tiles
          items={[
            ['정상 반영 건수', result ? result.successCount : 0],
            ['오류 행 건수', errorRows.length],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>오류 행</h2>
        <Band total={errorRows.length}>
          <button type="button" onClick={() => setOpen(true)}>엑셀 업로드</button>
        </Band>
        <DataTable
          columns={[
            { key: 'row', label: '행 번호' },
            { key: 'reason', label: '오류 사유' },
          ]}
          rows={errorRows}
          empty="오류 행이 없습니다."
        />
        {result === undefined ? <ErrorText text="" /> : null}
      </section>
      {open ? (
        <Drawer title="자산정보 엑셀 업로드" onClose={() => setOpen(false)}>
          <Form
            onSubmit={submit}
            submit="업로드"
            note="첫 줄은 양식 머리글(자산코드, 자산번호, 자산명, 자산유형, 자산분류, 위치, 취득일, 취득원가, 상각여부, 상각방법, 내용연수, 상각시작일)이어야 합니다."
          >
            <Field label="자산정보 엑셀 파일" required wide>
              <TextInput value={file} onChange={setFile} multiline placeholder="양식에 맞는 내용을 붙여 넣으세요" />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
